static inline uint32_t g2p_djb2(const char *s, int len) {
    uint32_t h = 5381;
    for (int i = 0; i < len; i++)
        h = ((h << 5) + h) ^ (uint8_t)s[i];
    return h;
}

/*
 * Look up a word in the G2P table.
 * word: lowercase ASCII word (not null-terminated, length given)
 * out_ids: output phoneme token IDs
 * max_ids: capacity of out_ids
 * Returns number of phoneme IDs written, or 0 if not found.
 */
static int g2p_lookup(const char *word, int word_len, int *out_ids, int max_ids) {
    uint32_t h = g2p_djb2(word, word_len) % G2P_TABLE_SIZE;
    for (int probe = 0; probe < G2P_TABLE_SIZE; probe++) {
        uint32_t w_packed = g2p_table[h][0];
        uint32_t p_packed = g2p_table[h][1];
        if (w_packed == 0xFFFFFFFF) return 0; /* empty slot */
        int wo = (int)(w_packed >> 8);
        int wl = (int)(w_packed & 0xFF);
        if (wl == word_len && memcmp(g2p_word_pool + wo, word, wl) == 0) {
            int po = (int)(p_packed >> 8);
            int pl = (int)(p_packed & 0xFF);
            if (pl > max_ids) pl = max_ids;
            for (int i = 0; i < pl; i++)
                out_ids[i] = g2p_phone_pool[po + i];
            return pl;
        }
        h = (h + 1) % G2P_TABLE_SIZE;
    }
    return 0;
}

